package com.commercecore.order;
import com.commercecore.audit.AuditService;import com.commercecore.cart.*;import com.commercecore.common.exception.ApiException;import com.commercecore.config.CheckoutProperties;import org.springframework.context.ApplicationEventPublisher;import com.commercecore.inventory.*;import com.commercecore.promotion.PromotionService;import com.commercecore.shipping.*;import com.commercecore.user.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;
@Service public class OrderService{
 private final CustomerOrderRepository orders;private final OrderItemRepository items;private final OrderAddressRepository snapshots;private final OrderStatusHistoryRepository history;private final ShipmentRepository shipments;private final ShipmentTrackingEventRepository tracking;private final UserAccountRepository users;private final AddressRepository addresses;private final CartService carts;private final InventoryService inventory;private final InventoryReservationRepository reservations;private final PromotionService promotions;private final ShippingQuoteService shipping;private final TaxCalculator taxes;private final CheckoutProperties properties;private final Clock clock;private final ApplicationEventPublisher publisher;private final AuditService audits;
 public OrderService(CustomerOrderRepository orders,OrderItemRepository items,OrderAddressRepository snapshots,OrderStatusHistoryRepository history,ShipmentRepository shipments,ShipmentTrackingEventRepository tracking,UserAccountRepository users,AddressRepository addresses,CartService carts,InventoryService inventory,InventoryReservationRepository reservations,PromotionService promotions,ShippingQuoteService shipping,TaxCalculator taxes,CheckoutProperties properties,Clock clock,ApplicationEventPublisher publisher,AuditService audits){this.publisher=publisher;this.orders=orders;this.items=items;this.snapshots=snapshots;this.history=history;this.shipments=shipments;this.tracking=tracking;this.users=users;this.addresses=addresses;this.carts=carts;this.inventory=inventory;this.reservations=reservations;this.promotions=promotions;this.shipping=shipping;this.taxes=taxes;this.properties=properties;this.clock=clock;this.audits=audits;}
 @Transactional public OrderDtos.OrderResponse checkout(UUID customerId,String rawKey,OrderDtos.CheckoutRequest request){String key=idempotencyKey(rawKey);UUID billingId=request.billingAddressId()==null?request.shippingAddressId():request.billingAddressId();String fingerprint=fingerprint(request.shippingAddressId(),billingId,request.shippingServiceLevel());Optional<CustomerOrder>early=orders.findByCustomerIdAndIdempotencyKey(customerId,key);if(early.isPresent())return existing(early.get(),fingerprint);Cart cart=carts.lockForCheckout(customerId);Optional<CustomerOrder>afterLock=orders.findByCustomerIdAndIdempotencyKey(customerId,key);if(afterLock.isPresent())return existing(afterLock.get(),fingerprint);Address ship=addresses.findByIdAndUserId(request.shippingAddressId(),customerId).orElseThrow(()->error(HttpStatus.NOT_FOUND,"SHIPPING_ADDRESS_NOT_FOUND","Shipping address was not found."));Address bill=addresses.findByIdAndUserId(billingId,customerId).orElseThrow(()->error(HttpStatus.NOT_FOUND,"BILLING_ADDRESS_NOT_FOUND","Billing address was not found."));CartService.CheckoutSnapshot priced;try{priced=carts.checkoutSnapshot(cart);}catch(ApiException e){throw error(e.getStatus(),"CHECKOUT_NOT_READY",e.getMessage());}ShippingQuoteService.Quote quote;try{quote=shipping.quote(request.shippingServiceLevel());}catch(RuntimeException e){throw error(HttpStatus.BAD_REQUEST,"INVALID_SHIPPING_METHOD","Shipping method is invalid.");}BigDecimal shippingDiscount=priced.freeShipping()?quote.fee():money(BigDecimal.ZERO);BigDecimal shippingFee=money(quote.fee().subtract(shippingDiscount));BigDecimal tax=taxes.calculate(priced.discountedMerchandiseTotal());BigDecimal grand=money(priced.discountedMerchandiseTotal().add(shippingFee).add(tax));UserAccount customer=users.findById(customerId).orElseThrow(OrderService::notFound);Instant expires=clock.instant().plus(properties.reservationTtl());CustomerOrder order=new CustomerOrder(number(),customer,key,fingerprint,priced.subtotal(),priced.merchandiseDiscount(),priced.discountedMerchandiseTotal(),quote.fee(),shippingDiscount,shippingFee,tax,grand,priced.promotion(),priced.merchandiseDiscount(),request.shippingServiceLevel(),quote.estimatedDeliveryDays(),expires);orders.saveAndFlush(order);snapshots.save(new OrderAddress(order,OrderAddressType.SHIPPING,ship));snapshots.save(new OrderAddress(order,OrderAddressType.BILLING,bill));for(CartService.CheckoutLine line:priced.lines()){OrderItem item=items.saveAndFlush(new OrderItem(order,line.selection().product(),line.selection().variant(),line.cartItem().getQuantity(),line.unitPrice()));String reference="ORDER:"+order.getId()+":ITEM:"+item.getId();try{InventoryDtos.ReservationResponse reserved=inventory.reserve(line.selection().inventory().getId(),new InventoryDtos.ReservationRequest(item.getQuantity(),reference,expires),null);item.linkReservation(reservations.findById(reserved.id()).orElseThrow());}catch(ApiException changed){throw error(HttpStatus.CONFLICT,"CHECKOUT_STOCK_CHANGED","Inventory changed during checkout; no order was created.");}}record(order,null,OrderStatus.PENDING,customerId,"CHECKOUT_CREATED",key);carts.clearAfterCheckout(cart);return response(order);}
 @Transactional(readOnly=true)public OrderDtos.PageResponse<OrderDtos.OrderResponse> customerOrders(UUID customerId,int page,int size){Page<CustomerOrder>result=orders.findAll((root,q,cb)->cb.equal(root.get("customer").get("id"),customerId),page(page,size,Sort.by(Sort.Direction.DESC,"createdAt")));return pageResponse(result);}
 @Transactional(readOnly=true)public OrderDtos.OrderResponse customerOrder(UUID customerId,UUID id){return response(orders.findByIdAndCustomerId(id,customerId).orElseThrow(OrderService::notFound));}
 @Transactional public OrderDtos.OrderResponse cancelCustomer(UUID customerId,UUID id){CustomerOrder order=locked(id);if(!order.getCustomer().getId().equals(customerId))throw notFound();return cancel(order,customerId,"CUSTOMER_CANCELLED",false);}
 @Transactional public OrderDtos.OrderResponse cancelStaff(UUID actor,UUID id){return cancel(locked(id),actor,"STAFF_CANCELLED",false);}
 @Transactional public OrderDtos.OrderResponse confirmAfterPayment(UUID id,String paymentReference){CustomerOrder order=locked(id);if(order.getStatus()==OrderStatus.CONFIRMED)return response(order);if(order.getStatus()!=OrderStatus.PENDING)throw invalidTransition();if(!clock.instant().isBefore(order.getReservationExpiresAt()))throw error(HttpStatus.CONFLICT,"RESERVATION_EXPIRED","The order reservation has expired.");for(OrderItem item:items.findAllByOrderIdOrderByCreatedAtAscIdAsc(id)){InventoryReservation reservation=requiredReservation(item);if(reservation.getStatus()!=ReservationStatus.ACTIVE)throw error(HttpStatus.CONFLICT,"RESERVATION_EXPIRED","An order reservation is no longer active.");inventory.confirm(reservation.getId(),null);}if(order.getPromotion()!=null)promotions.recordRedemption(order.getPromotion().getId(),order.getCustomer().getId(),"ORDER:"+order.getId());transition(order,OrderStatus.CONFIRMED,null,"PAYMENT_CONFIRMED",paymentReference);return response(order);}
 @Transactional public int expirePendingOrders(){int count=0;Instant now=clock.instant();for(CustomerOrder candidate:orders.findAllByStatusAndReservationExpiresAtLessThanEqual(OrderStatus.PENDING,now)){CustomerOrder order=locked(candidate.getId());if(order.getStatus()==OrderStatus.PENDING&&!order.getReservationExpiresAt().isAfter(now)){cancel(order,null,"RESERVATION_EXPIRED",true);count++;}}return count;}
 @Transactional public OrderDtos.OrderResponse processing(UUID actor,UUID id){CustomerOrder order=locked(id);transition(order,OrderStatus.PROCESSING,actor,"PROCESSING_STARTED",null);return response(order);}
 @Transactional public OrderDtos.OrderResponse createShipment(UUID actor,UUID id,OrderDtos.ShipmentRequest request){CustomerOrder order=locked(id);if(order.getStatus()!=OrderStatus.CONFIRMED&&order.getStatus()!=OrderStatus.PROCESSING)throw invalidTransition();if(shipments.existsByOrderId(id))throw error(HttpStatus.CONFLICT,"INVALID_TRACKING_DATA","A shipment already exists for this order.");Shipment shipment;try{Instant estimated=request.estimatedDeliveryAt()==null?clock.instant().plus(Duration.ofDays(order.getShippingEstimatedDays())):request.estimatedDeliveryAt();shipment=shipments.saveAndFlush(new Shipment(order,request.carrier(),request.trackingNumber(),estimated));tracking.save(new ShipmentTrackingEvent(shipment,TrackingStatus.LABEL_CREATED,null,"Shipping label created",clock.instant()));}catch(RuntimeException e){throw error(HttpStatus.BAD_REQUEST,"INVALID_TRACKING_DATA","Shipment tracking data is invalid.");}return response(order);}
 @Transactional public OrderDtos.OrderResponse addTracking(UUID actor,UUID id,OrderDtos.TrackingEventRequest request){CustomerOrder order=locked(id);Shipment shipment=shipments.findByOrderId(id).orElseThrow(OrderService::shipmentNotFound);try{tracking.save(new ShipmentTrackingEvent(shipment,request.status(),request.location(),request.note(),request.occurredAt()));}catch(IllegalArgumentException e){throw error(HttpStatus.BAD_REQUEST,"INVALID_TRACKING_DATA","Tracking event is invalid.");}return response(order);}
 @Transactional public OrderDtos.OrderResponse ship(UUID actor,UUID id){CustomerOrder order=locked(id);if(order.getStatus()!=OrderStatus.PROCESSING)throw invalidTransition();Shipment shipment=shipments.findByOrderId(id).orElseThrow(OrderService::shipmentNotFound);Instant now=clock.instant();shipment.shipped(now);tracking.save(new ShipmentTrackingEvent(shipment,TrackingStatus.PICKED_UP,null,"Shipment handed to carrier",now));transition(order,OrderStatus.SHIPPED,actor,"ORDER_SHIPPED",shipment.getTrackingNumber());return response(order);}
 @Transactional public OrderDtos.OrderResponse deliver(UUID actor,UUID id){CustomerOrder order=locked(id);if(order.getStatus()!=OrderStatus.SHIPPED)throw invalidTransition();Shipment shipment=shipments.findByOrderId(id).orElseThrow(OrderService::shipmentNotFound);Instant now=clock.instant();shipment.delivered(now);tracking.save(new ShipmentTrackingEvent(shipment,TrackingStatus.DELIVERED,null,"Shipment delivered",now));transition(order,OrderStatus.DELIVERED,actor,"ORDER_DELIVERED",shipment.getTrackingNumber());return response(order);}
 @Transactional(readOnly=true)public OrderDtos.ShipmentResponse customerTracking(UUID customerId,UUID id){CustomerOrder order=orders.findByIdAndCustomerId(id,customerId).orElseThrow(OrderService::notFound);return shipmentResponse(shipments.findByOrderId(order.getId()).orElseThrow(OrderService::shipmentNotFound));}
 @Transactional(readOnly=true)public OrderDtos.OrderResponse staffOrder(UUID id){return response(orders.findById(id).orElseThrow(OrderService::notFound));}
 @Transactional(readOnly=true)public OrderDtos.PageResponse<OrderDtos.OrderResponse> staffOrders(String number,OrderStatus status,UUID customerId,String email,Instant from,Instant to,int page,int size){Specification<CustomerOrder>spec=(root,q,cb)->cb.conjunction();if(number!=null&&!number.isBlank())spec=spec.and((r,q,c)->c.like(c.lower(r.get("orderNumber")),"%"+number.trim().toLowerCase(Locale.ROOT)+"%"));if(status!=null)spec=spec.and((r,q,c)->c.equal(r.get("status"),status));if(customerId!=null)spec=spec.and((r,q,c)->c.equal(r.get("customer").get("id"),customerId));if(email!=null&&!email.isBlank())spec=spec.and((r,q,c)->c.equal(r.get("customer").get("email"),email.trim().toLowerCase(Locale.ROOT)));if(from!=null)spec=spec.and((r,q,c)->c.greaterThanOrEqualTo(r.get("createdAt"),from));if(to!=null)spec=spec.and((r,q,c)->c.lessThanOrEqualTo(r.get("createdAt"),to));return pageResponse(orders.findAll(spec,page(page,size,Sort.by(Sort.Direction.DESC,"createdAt"))));}
 private OrderDtos.OrderResponse cancel(CustomerOrder order,UUID actor,String reason,boolean expire){if(order.getStatus()==OrderStatus.CANCELLED)return response(order);if(order.getStatus()!=OrderStatus.PENDING)throw error(HttpStatus.CONFLICT,"ORDER_CANCELLATION_REQUIRES_REFUND","Only pending orders can be cancelled before payment/refund support exists.");for(OrderItem item:items.findAllByOrderIdOrderByCreatedAtAscIdAsc(order.getId())){InventoryReservation r=requiredReservation(item);if(r.getStatus()==ReservationStatus.ACTIVE){if(expire)inventory.expire(r.getId(),actor);else inventory.release(r.getId(),actor);}}transition(order,OrderStatus.CANCELLED,actor,reason,null);return response(order);}
 private void transition(CustomerOrder order,OrderStatus target,UUID actor,String reason,String reference){OrderStatus from=order.getStatus();try{order.transition(target);}catch(IllegalStateException e){throw invalidTransition();}record(order,from,target,actor,reason,reference);}private void record(CustomerOrder order,OrderStatus from,OrderStatus to,UUID actor,String reason,String reference){Instant occurredAt=clock.instant();history.save(new OrderStatusHistory(order,from,to,actor,reason,reference,occurredAt));publisher.publishEvent(new OrderStatusChangedEvent(order.getId(),order.getCustomer().getId(),order.getOrderNumber(),from,to,actor,reason,reference,occurredAt));
 if(from==null)return; // Initial checkout creation: status history only, no audit entry.
 String details="orderNumber="+order.getOrderNumber()+"; from="+from+"; to="+to
         +(reason==null?"":"; reason="+reason);
 if(to==OrderStatus.CANCELLED){
     audits.record(actor,"ORDER_CANCELLED","ORDER","ORDER",order.getId().toString(),details);
 }else{
     audits.record(actor,"ORDER_STATUS_CHANGED","ORDER","ORDER",order.getId().toString(),details);
 }}
 private InventoryReservation requiredReservation(OrderItem item){return Optional.ofNullable(item.getInventoryReservation()).orElseThrow(()->error(HttpStatus.CONFLICT,"RESERVATION_EXPIRED","Order reservation is missing."));}private CustomerOrder locked(UUID id){return orders.findLockedById(id).orElseThrow(OrderService::notFound);}private OrderDtos.OrderResponse existing(CustomerOrder order,String fingerprint){if(!order.getRequestFingerprint().equals(fingerprint))throw error(HttpStatus.CONFLICT,"CHECKOUT_IDEMPOTENCY_CONFLICT","Idempotency key was already used for a different checkout request.");return response(order);}
 private OrderDtos.OrderResponse response(CustomerOrder o){List<OrderDtos.ItemSnapshot>itemDtos=items.findAllByOrderIdOrderByCreatedAtAscIdAsc(o.getId()).stream().map(i->new OrderDtos.ItemSnapshot(i.getId(),i.getSourceProduct()==null?null:i.getSourceProduct().getId(),i.getSourceVariant()==null?null:i.getSourceVariant().getId(),i.getProductName(),i.getSku(),i.getQuantity(),i.getUnitPrice(),i.getLineSubtotal(),i.getAttributes().stream().map(a->new OrderDtos.AttributeSnapshot(a.getName(),a.getValue(),a.getDisplayOrder())).toList())).toList();List<OrderDtos.AddressSnapshot>addressDtos=snapshots.findAllByOrderIdOrderByTypeAsc(o.getId()).stream().map(a->new OrderDtos.AddressSnapshot(a.getType(),a.getSourceAddressId(),a.getRecipientName(),a.getPhone(),a.getAddressLine1(),a.getAddressLine2(),a.getCity(),a.getStateRegion(),a.getPostalCode(),a.getCountryCode())).toList();List<OrderDtos.StatusEvent>events=history.findAllByOrderIdOrderByOccurredAtAscIdAsc(o.getId()).stream().map(h->new OrderDtos.StatusEvent(h.getFromStatus(),h.getToStatus(),h.getActorUserId(),h.getReason(),h.getReference(),h.getOccurredAt())).toList();OrderDtos.PromotionSnapshot promo=o.getPromotion()==null?null:new OrderDtos.PromotionSnapshot(o.getPromotion().getId(),o.getPromotionCode(),o.getPromotionName(),o.getPromotionType(),o.getPromotionDiscount(),o.getPromotionType()==com.commercecore.promotion.PromotionType.FREE_SHIPPING);OrderDtos.ShipmentResponse shipment=shipments.findByOrderId(o.getId()).map(this::shipmentResponse).orElse(null);return new OrderDtos.OrderResponse(o.getId(),o.getOrderNumber(),o.getStatus(),itemDtos,addressDtos,o.getSubtotal(),o.getMerchandiseDiscount(),o.getDiscountedMerchandiseTotal(),o.getShippingFeeBeforeDiscount(),o.getShippingDiscount(),o.getShippingFee(),o.getTaxAmount(),o.getGrandTotal(),promo,o.getShippingServiceLevel(),o.getShippingEstimatedDays(),o.getReservationExpiresAt(),o.getCreatedAt(),o.getUpdatedAt(),events,shipment);}
 private OrderDtos.ShipmentResponse shipmentResponse(Shipment s){return new OrderDtos.ShipmentResponse(s.getId(),s.getServiceLevel(),s.getCarrier(),s.getTrackingNumber(),s.getEstimatedDeliveryAt(),s.getShippedAt(),s.getDeliveredAt(),tracking.findAllByShipmentIdOrderByOccurredAtAscIdAsc(s.getId()).stream().map(e->new OrderDtos.TrackingEvent(e.getStatus(),e.getLocation(),e.getNote(),e.getOccurredAt())).toList());}private OrderDtos.PageResponse<OrderDtos.OrderResponse>pageResponse(Page<CustomerOrder>p){return new OrderDtos.PageResponse<>(p.getContent().stream().map(this::response).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages(),p.isFirst(),p.isLast());}
 private static Pageable page(int page,int size,Sort sort){if(page<0||size<1||size>100)throw error(HttpStatus.BAD_REQUEST,"VALIDATION_FAILED","Page parameters are invalid.");return PageRequest.of(page,size,sort);}private static String idempotencyKey(String key){if(key==null||key.isBlank()||key.trim().length()<8||key.trim().length()>160)throw error(HttpStatus.BAD_REQUEST,"VALIDATION_FAILED","Idempotency-Key must contain 8 to 160 characters.");return key.trim();}private static String fingerprint(UUID shipping,UUID billing,ShippingServiceLevel level){if(shipping==null||billing==null||level==null)throw error(HttpStatus.BAD_REQUEST,"VALIDATION_FAILED","Checkout request is incomplete.");try{byte[]hash=MessageDigest.getInstance("SHA-256").digest((shipping+"|"+billing+"|"+level).getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(hash);}catch(Exception e){throw new IllegalStateException(e);}}private static String number(){String random=UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);return "CC-"+LocalDate.now(ZoneOffset.UTC).toString().replace("-","")+"-"+random;}private static BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}private static ApiException notFound(){return error(HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Order was not found.");}private static ApiException shipmentNotFound(){return error(HttpStatus.NOT_FOUND,"SHIPMENT_NOT_FOUND","Shipment was not found.");}private static ApiException invalidTransition(){return error(HttpStatus.CONFLICT,"INVALID_ORDER_TRANSITION","Order cannot perform this transition.");}private static ApiException error(HttpStatus s,String c,String m){return new ApiException(s,c,m);}
}
